mapper.select:
select id userId, tel_no telNo, im_id imId
from corgi_user_login
where tel_no = #{telNo}

select id userId, tel_no telNo, im_id imId
from corgi_user_login
where id = #{userId}

mapper.update:
update corgi_user_login
set im_id = #{userLogin.imId}
where id = #{userLogin.userId}

update corgi_user_login
set im_id = #{userLogin.imId},
tel_no = #{userLogin.telNo}
where id = #{userLogin.userId}

mapper.select:
select count(1) from corgi_user_detail

    where `nickname` = #{nickname} or `checkNickname` = #{nickname}


    where `nickname` = #{checkNickname} or `checkNickname` = #{checkNickname}

mapper.update:
update corgi_user_detail
set `nickname` = #{nickname}, check_nickname = #{checkNickname}
where user_id = #{userId}

update corgi_user_detail
set avatar_status = #{status}
where avatar_data_id = #{dataId}

update corgi_user_detail
set avatar = null, avatar_status = null, avatar_data_id = null
where avatar_data_id = #{dataId}

mapper.select:
select p.user_id from corgi_user_position p left join corgi_user_detail d on p.user_id = d.user_id
where p.lat >= #{range.beginLat} and p.lat <= #{range.endLat}
and p.lng >= #{range.beginLng} and p.lng <= #{range.endLng}

    and d.height >= #{range.startHeight}


    and d.height <= #{range.endHeight}


    and d.height >= #{range.startWeight}


    and d.height <= #{range.endWeight}



    and d.role in ${range.role}


    and d.group in ${range.group}

select
d.user_id userId,
d.nickname nickname,
d.check_nickname checkNickname,
d.avatar avatar,
d.avatar_status avatarStatus,
d.role role,
d.group `group`,
d.con con,
d.desc,
d.check_desc checkDesc,
l.im_id imId,
l.tel_no telNo,
p.uptime `time`
from corgi_user_detail d
left join corgi_user_login l on l.id = d.user_id
left join corgi_user_position p on p.user_id = d.user_id
where 1=1

    and `nickName` like concat('%',#{userDetail.nickname},'%')


    and `height` = #{userDetail.height}


    and `weight` = #{userDetail.weight}


    and `desc` like concat('%',#{userDetail.desc},'%')


    and `role` = #{userDetail.role}


    and `character` = #{userDetail.character}


    and `group` = #{userDetail.group}


    and `birthday` = #{userDetail.birthday}


    and `city` = #{userDetail.city}


    and `con` = #{userDetail.con}


    and user_id = #{userDetail.userId}


    and tel_no = #{userDetail.telNo}

limit #{start},#{size}

select
count(1)
from corgi_user_detail d
left join corgi_user_login l on l.id = d.user_id
where 1=1

    and `nickName` like concat('%',#{userDetail.nickname},'%')


    and `height` = #{userDetail.height}


    and `weight` = #{userDetail.weight}


    and `desc` like concat('%',#{userDetail.desc},'%')


    and `role` = #{userDetail.role}


    and `character` = #{userDetail.character}


    and `group` = #{userDetail.group}


    and `birthday` = #{userDetail.birthday}


    and `city` = #{userDetail.city}


    and `con` = #{userDetail.con}


    and user_id = #{userDetail.userId}


    and tel_no = #{userDetail.telNo}

select distinct d.user_id from corgi_user_detail d
left join corgi_prefer_group g on g.user_id = d.user_id
where d.user_id in ${userId}

    and d.role in ${role}


    and d.group in ${group}


    and g.group in ${preferGroup}
